from __future__ import annotations

import json
import re
from typing import Any, Dict, List

from agents import build_agents, run_agent
from tools import Chunk, run_searxng, search_local


def _extract_json(text: str) -> Dict[str, Any]:
    match = re.search(r"\{.*\}", text, re.DOTALL)
    if not match:
        return {}
    try:
        return json.loads(match.group(0))
    except json.JSONDecodeError:
        return {}


def _summarize_chunks(chunks: List[Chunk]) -> str:
    lines = []
    for chunk in chunks:
        snippet = chunk.text[:300].strip()
        lines.append(f"- {chunk.doc_name} [chunk {chunk.chunk_id}]: {snippet}")
    return "\n".join(lines)


def run_pipeline(
    question: str,
    local_chunks: List[Chunk],
    api_key: str,
    model: str,
    web_enabled: bool,
    searxng_base_url: str,
) -> Dict[str, Any]:
    agents = build_agents(api_key=api_key, model=model)

    doc_summary = "No local documents provided."
    if local_chunks:
        doc_names = sorted({chunk.doc_name for chunk in local_chunks})
        doc_summary = f"Local docs: {', '.join(doc_names)} (total chunks: {len(local_chunks)})"

    triage_prompt = f"""
Question: {question}
{doc_summary}

Decide the best route. Output JSON with keys:
- route: "local" or "web"
- confidence: number 0 to 1
- rationale: short string
"""
    triage_raw = run_agent(agents["triage"], triage_prompt)
    triage = _extract_json(triage_raw)

    route = triage.get("route", "local")
    if not local_chunks and web_enabled:
        route = "web"

    evidence: List[Dict[str, Any]] = []
    draft_answer = ""

    if route == "web" and web_enabled:
        search_results = run_searxng(question, base_url=searxng_base_url, max_results=5)
        formatted_results = "\n".join(
            [
                f"- {item.get('title', 'Untitled')} | {item.get('link', '')} | {item.get('snippet', '')}"
                for item in search_results
            ]
        )
        web_prompt = f"""
Question: {question}

Web results:
{formatted_results}

Return JSON with keys:
- evidence: list of {{source, summary}}
- draft_answer: string
"""
        web_raw = run_agent(agents["web"], web_prompt)
        web_json = _extract_json(web_raw)
        evidence = web_json.get("evidence", [])
        draft_answer = web_json.get("draft_answer", "")
    else:
        hits = search_local(question, local_chunks, top_k=5)
        formatted_hits = _summarize_chunks(hits)
        local_prompt = f"""
Question: {question}

Document excerpts:
{formatted_hits}

Return JSON with keys:
- evidence: list of {{source, summary}}
- draft_answer: string
"""
        local_raw = run_agent(agents["local"], local_prompt)
        local_json = _extract_json(local_raw)
        evidence = local_json.get("evidence", [])
        draft_answer = local_json.get("draft_answer", "")

    verifier_prompt = f"""
Question: {question}

Draft answer:
{draft_answer}

Evidence:
{json.dumps(evidence, indent=2)}

Return JSON with keys:
- verdict: "sufficient" or "insufficient"
- gaps: list of short strings
"""
    verifier_raw = run_agent(agents["verifier"], verifier_prompt)
    verifier = _extract_json(verifier_raw)

    synth_prompt = f"""
Question: {question}

Draft answer:
{draft_answer}

Evidence:
{json.dumps(evidence, indent=2)}

Verifier verdict:
{json.dumps(verifier, indent=2)}

Provide the final answer with clear citations to the evidence sources.
"""
    final_answer = run_agent(agents["synthesizer"], synth_prompt)

    return {
        "route": route,
        "triage": triage,
        "evidence": evidence,
        "verifier": verifier,
        "final_answer": final_answer,
    }

import { analyse, type AnalyseResult } from "./lang.js";
import type { QuestionDef, SystemOneResult } from "./agent.js";

export const BUNDLE_REPO = "convaiinnovations/laya";

export interface ModelSpec {
  repo: string;
  subfolder: string | null;
}

export const DEFAULT_MODELS: Record<string, ModelSpec> = {
  english: { repo: BUNDLE_REPO, subfolder: null },
  multilingual: { repo: BUNDLE_REPO, subfolder: "multilingual" },
  "typed-decisions": { repo: BUNDLE_REPO, subfolder: "typed-decisions" },
};

export const STANDALONE_MODELS: Record<string, string> = {
  english: "convaiinnovations/laya",
  multilingual: "convaiinnovations/laya-multilingual",
  "typed-decisions": "convaiinnovations/laya-typed-decisions",
};

export type ModelName = "english" | "multilingual" | "typed-decisions";

const ALIASES: Record<string, ModelName> = {
  en: "english",
  laya: "english",
  default: "english",
  multi: "multilingual",
  ml: "multilingual",
  "laya-multilingual": "multilingual",
  typed: "typed-decisions",
  typed_decisions: "typed-decisions",
  "laya-typed-decisions": "typed-decisions",
  decisions: "typed-decisions",
};

export function normaliseName(name: string): ModelName {
  const raw = String(name).trim().toLowerCase();
  const key = ALIASES[raw] ?? raw;
  if (!(key in DEFAULT_MODELS)) {
    throw new Error(
      `unknown model ${JSON.stringify(name)}; choose one of ${JSON.stringify(
        Object.keys(DEFAULT_MODELS).sort(),
      )} (or an alias: ${JSON.stringify(Object.keys(ALIASES).sort())})`,
    );
  }
  return key as ModelName;
}

const TYPED_DECISION_WORKFLOWS: Record<string, Set<string>> = {
  agent_trace_observability: new Set(["action", "needs_review", "outcome", "risk", "urgency"]),
  customer_service: new Set(["action", "category", "churn_risk", "needs_human", "urgency"]),
  invoice_processing: new Set(["discrepancy_severity", "disposition", "duplicate", "matches_order", "urgency"]),
  security_incidents: new Set(["credential_compromise", "disposition", "severity", "true_positive", "urgency"]),
};

export function matchTypedDecisionsWorkflow(
  questions: Record<string, unknown> | null | undefined,
): string | null {
  const ids = new Set(Object.keys(questions ?? {}));
  for (const [wf, sig] of Object.entries(TYPED_DECISION_WORKFLOWS)) {
    if (ids.size !== sig.size) continue;
    let same = true;
    for (const id of sig) {
      if (!ids.has(id)) {
        same = false;
        break;
      }
    }
    if (same) return wf;
  }
  return null;
}

const ENGLISH_SUBTAGS = new Set(["en", "eng", "english"]);

export function englishFromCode(value: unknown): boolean | null {
  if (value === null || value === undefined) return null;
  let code = String(value).trim().toLowerCase();
  if (!code) return null;
  code = code.split(".", 1)[0]; // en_US.UTF-8 -> en_US
  const primary = code.replace(/_/g, "-").split("-", 1)[0]; // en_US -> en
  if (!primary) return null;
  return ENGLISH_SUBTAGS.has(primary);
}

/** Parity alias for the Python `_english_from_code` name. */
export const _englishFromCode = englishFromCode;

export interface RouteDecision {
  model: ModelName;
  repo: string;
  reason: string;
  detection: AnalyseResult | null;
  workflow: string | null;
}

export type RoutedResult = SystemOneResult & { routing: RouteDecision };

export type LangGuess = string | null | undefined | ((state: unknown) => unknown);

export type AgentLoader = (name: ModelName, spec: ModelSpec) => unknown | Promise<unknown>;

export interface RouterOptions {
  models?: Record<string, string | ModelSpec | [string, string | null]>;
  device?: string | null;
  token?: string | null;
  maxLoaded?: number;
  max_loaded?: number;
  default?: string;
  autoTaskDetection?: boolean;
  auto_task_detection?: boolean;
  standaloneRepos?: boolean;
  standalone_repos?: boolean;
  preload?: boolean | string[];
  langGuess?: LangGuess;
  lang_guess?: LangGuess;
  loader?: AgentLoader;
}

export interface RouteOptions {
  model?: string | null;
  task?: string | null;
  lang?: string | null;
  langGuess?: LangGuess;
  lang_guess?: LangGuess;
}

function toSpec(spec: string | ModelSpec | [string, string | null]): ModelSpec {
  if (typeof spec === "string") return { repo: spec, subfolder: null };
  if (Array.isArray(spec)) {
    const [repo, sub] = [...spec, null].slice(0, 2) as [string, string | null];
    return { repo, subfolder: sub ?? null };
  }
  return { repo: spec.repo, subfolder: spec.subfolder ?? null };
}

function repoStr(spec: ModelSpec): string {
  return spec.subfolder ? `${spec.repo}/${spec.subfolder}` : spec.repo;
}

export class Router {
  models: Record<string, ModelSpec>;
  device: string | null;
  token: string | null | undefined;
  maxLoaded: number;
  default: ModelName;
  autoTaskDetection: boolean;
  langGuess: LangGuess;
  loader: AgentLoader | null;
  _agents: Map<string, unknown> = new Map();
  _order: string[] = []; // least-recently-used first

  constructor(opts: RouterOptions = {}) {
    const base: Record<string, string | ModelSpec> = opts.standaloneRepos ?? opts.standalone_repos
      ? { ...STANDALONE_MODELS }
      : Object.fromEntries(Object.entries(DEFAULT_MODELS).map(([k, v]) => [k, { ...v }]));
    this.models = Object.fromEntries(Object.entries(base).map(([k, v]) => [k, toSpec(v)]));
    if (opts.models) {
      for (const [k, v] of Object.entries(opts.models)) {
        this.models[normaliseName(k)] = toSpec(v);
      }
    }
    this.device = opts.device ?? null;
    this.token = opts.token ?? (typeof process !== "undefined" ? process.env?.["HF_TOKEN"] : undefined);
    this.maxLoaded = Math.max(1, Math.trunc(Number(opts.maxLoaded ?? opts.max_loaded ?? 2)));
    this.default = normaliseName(opts.default ?? "english");
    this.autoTaskDetection = Boolean(opts.autoTaskDetection ?? opts.auto_task_detection ?? false);
    this.langGuess = opts.langGuess ?? opts.lang_guess ?? null;
    this.loader = opts.loader ?? null;
    if (opts.preload === true) {
      void this.preload();
    } else if (Array.isArray(opts.preload)) {
      void this.preload(opts.preload);
    }
  }

  async load(name: string): Promise<unknown> {
    const key = normaliseName(name);
    if (this._agents.has(key)) {
      this._touch(key);
      return this._agents.get(key);
    }
    let agent: unknown;
    if (this.loader) {
      agent = await this.loader(key, this.models[key]);
    } else {
      const { Agent } = await import("./agent.js");
      const spec = this.models[key];
      agent = await (Agent as unknown as {
        load(repo: string, opts?: Record<string, unknown>): Promise<unknown>;
      }).load(spec.repo, {
        subfolder: spec.subfolder,
        device: this.device ?? undefined,
        token: this.token ?? undefined,
      });
    }
    this._agents.set(key, agent);
    this._order.push(key);
    this._evict();
    return agent;
  }

  _touch(key: string): void {
    const i = this._order.indexOf(key);
    if (i !== -1) this._order.splice(i, 1);
    this._order.push(key);
  }

  _evict(): void {
    while (this._order.length > this.maxLoaded) {
      const victim = this._order.shift()!;
      this._agents.delete(victim);
    }
    // Keep the two views consistent.
    if (this._order.length < this._agents.size) {
      for (const k of [...this._agents.keys()]) {
        if (!this._order.includes(k)) this._agents.delete(k);
      }
    }
  }

  attach(name: string, agent: unknown): unknown {
    const key = normaliseName(name);
    this._agents.set(key, agent);
    this._touch(key);
    this.maxLoaded = Math.max(this.maxLoaded, this._agents.size);
    return agent;
  }

  async preload(names?: string[]): Promise<this> {
    const keys = (names ?? Object.keys(this.models)).map((n) => normaliseName(n));
    this.maxLoaded = Math.max(this.maxLoaded, new Set([...keys, ...this._agents.keys()]).size);
    for (const n of keys) {
      if (!this._agents.has(n)) await this.load(n);
    }
    return this;
  }

  unload(name?: string | null): void {
    if (name === null || name === undefined) {
      this._agents.clear();
      this._order = [];
    } else {
      const key = normaliseName(name);
      this._agents.delete(key);
      const i = this._order.indexOf(key);
      if (i !== -1) this._order.splice(i, 1);
    }
  }

  get loaded(): string[] {
    return [...this._order];
  }

  _resolveHint(hint: LangGuess, state: unknown): boolean | null {
    if (hint === null || hint === undefined) return null;
    const value = typeof hint === "function" ? (hint as (s: unknown) => unknown)(state) : hint;
    return englishFromCode(value);
  }

  route(
    state: unknown,
    questions: Record<string, unknown> | null = null,
    opts: RouteOptions = {},
  ): RouteDecision {
    const { model = null, task = null, lang = null } = opts;
    const langGuessOpt = opts.langGuess ?? opts.lang_guess ?? null;

    if (model !== null && model !== undefined) {
      const key = normaliseName(model);
      return {
        model: key,
        repo: repoStr(this.models[key]),
        reason: `explicit model=${JSON.stringify(model)}`,
        detection: null,
        workflow: null,
      };
    }

    if (task !== null && task !== undefined) {
      const t = String(task).toLowerCase().replace(/-/g, "_") === "typed_decisions" ? "typed-decisions" : task;
      const key = normaliseName(t);
      return {
        model: key,
        repo: repoStr(this.models[key]),
        reason: `explicit task=${JSON.stringify(task)}`,
        detection: null,
        workflow: null,
      };
    }

    const workflow = matchTypedDecisionsWorkflow(questions ?? {});
    if (workflow && this.autoTaskDetection) {
      return {
        model: "typed-decisions",
        repo: repoStr(this.models["typed-decisions"]),
        reason: `question ids match the ${JSON.stringify(workflow)} typed-decisions workflow`,
        detection: null,
        workflow,
      };
    }

    if (lang !== null && lang !== undefined) {
      const key: ModelName = englishFromCode(lang) ? "english" : "multilingual";
      return {
        model: key,
        repo: repoStr(this.models[key]),
        reason: `explicit lang=${JSON.stringify(lang)}`,
        detection: null,
        workflow,
      };
    }

    const hints: Array<[string, LangGuess]> = [
      ["lang_guess", langGuessOpt],
      ["Router(lang_guess=...)", this.langGuess],
    ];
    for (const [source, hint] of hints) {
      const resolved = this._resolveHint(hint, state);
      if (resolved !== null && resolved !== undefined) {
        const key: ModelName = resolved ? "english" : "multilingual";
        return {
          model: key,
          repo: repoStr(this.models[key]),
          reason: `${source}: the caller identified this as ${resolved ? "English" : "non-English"} text`,
          detection: null,
          workflow,
        };
      }
    }

    const det = analyse(state);
    let key: ModelName;
    let reason: string;
    if (det.script === "unknown") {
      key = this.default;
      reason = `no letters detected in state; using default (${key})`;
    } else if (det.script !== "latin") {
      key = "multilingual";
      reason =
        `non-Latin script (${det.script}, ${Math.round(100 * det.nonLatinFraction)}% of letters); ` +
        "the English checkpoint cannot read it";
    } else if (!det.isEnglish) {
      key = "multilingual";
      if (det.language) {
        reason = `Latin script but language looks like ${JSON.stringify(det.language)}, not English`;
      } else {
        reason =
          `Latin script, language not identified but ${Math.round(100 * det.diacriticRate)}% ` +
          "non-English letters; not safe for the English checkpoint";
      }
    } else if (det.languageUndecided) {
      key = this.default;
      reason = `Latin script, language not identified and no non-English letters; using default (${key})`;
    } else {
      key = "english";
      reason = "English Latin text";
    }
    return { model: key, repo: repoStr(this.models[key]), reason, detection: det, workflow };
  }

  async predict(
    state: unknown,
    questions: Record<string, QuestionDef>,
    opts: RouteOptions = {},
  ): Promise<RoutedResult> {
    const decision = this.route(state, questions, opts);
    const agent = (await this.load(decision.model)) as {
      systemOne(s: unknown, q: Record<string, QuestionDef>): Promise<SystemOneResult>;
    };
    const result = (await agent.systemOne(state, questions)) as RoutedResult;
    result["routing"] = { ...decision };
    return result;
  }

  async systemOne(
    state: unknown,
    questions: Record<string, QuestionDef>,
    opts: RouteOptions = {},
  ): Promise<RoutedResult> {
    return this.predict(state, questions, opts);
  }
}

package com.alibaba.android.arouter.core;

import android.app.Activity;
import android.app.Instrumentation;
import android.content.Intent;
import android.os.BadParcelableException;
import android.os.Parcel;
import android.os.Parcelable;

import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;

import com.alibaba.android.arouter.facade.template.ILogger;
import com.alibaba.android.arouter.launcher.ARouter;

import org.junit.BeforeClass;
import org.junit.Test;
import org.junit.runner.RunWith;

import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.fail;

@RunWith(AndroidJUnit4.class)
public class InstrumentationHookIntentRobustnessInstrumentedTest {

    @BeforeClass
    public static void enableLegacyAutoInjection() {
        ARouter.enableAutoInject();
    }

    @Test
    public void normalParcelledExtrasStillInjectIntoTheActivity() throws Exception {
        Intent intent = parcelIntent(new Intent()
                .putExtra(ARouter.AUTO_INJECT, new String[]{"message"})
                .putExtra("message", "normal-value"));

        HookActivity activity = newActivity(intent);

        assertEquals("normal-value", activity.message);
    }

    @Test
    public void malformedParcelableIsActuallyRejectedWhenItsExtraIsRead() {
        Intent intent = parcelledIntentWithMalformedExtra();

        try {
            intent.getExtras().get("message");
            fail("The parcelled extra must be malformed for this Intent robustness test");
        } catch (BadParcelableException expected) {
            assertNotNull(expected.getMessage());
        }
    }

    @Test
    public void malformedExtrasDoNotAbortActivityInstantiation() throws Exception {
        HookActivity activity = newActivity(parcelledIntentWithMalformedExtra());

        assertNotNull(activity);
        assertNull(activity.message);
    }

    @Test
    public void forgedAutoInjectFieldDoesNotAbortActivityInstantiationWhenLoggerIsUnavailable() throws Exception {
        Intent intent = new Intent()
                .putExtra(ARouter.AUTO_INJECT, new String[]{"missingField"})
                .putExtra("missingField", "untrusted-value");

        ILogger previousLogger = ARouter.logger;
        HookActivity activity;
        try {
            ARouter.logger = null;
            activity = newActivity(intent);
        } finally {
            ARouter.logger = previousLogger;
        }

        assertNotNull(activity);
        assertNull(activity.message);
    }

    private static HookActivity newActivity(Intent intent) throws Exception {
        final Instrumentation instrumentation = InstrumentationRegistry.getInstrumentation();
        final AtomicReference<HookActivity> activity = new AtomicReference<>();
        final AtomicReference<Throwable> failure = new AtomicReference<>();
        final Intent activityIntent = intent;
        instrumentation.runOnMainSync(new Runnable() {
            @Override
            public void run() {
                try {
                    activity.set((HookActivity) new InstrumentationHook().newActivity(
                            InstrumentationHookIntentRobustnessInstrumentedTest.class.getClassLoader(),
                            HookActivity.class.getName(),
                            activityIntent
                    ));
                } catch (Throwable throwable) {
                    failure.set(throwable);
                }
            }
        });

        Throwable throwable = failure.get();
        if (throwable instanceof Exception) {
            throw (Exception) throwable;
        }
        if (throwable instanceof Error) {
            throw (Error) throwable;
        }
        if (throwable != null) {
            throw new RuntimeException(throwable);
        }
        return activity.get();
    }

    private static Intent parcelledIntentWithMalformedExtra() {
        return parcelIntent(new Intent()
                .putExtra(ARouter.AUTO_INJECT, new String[]{"message"})
                .putExtra("message", new ThrowingParcelable()));
    }

    private static Intent parcelIntent(Intent source) {
        Parcel parcel = Parcel.obtain();
        try {
            source.writeToParcel(parcel, 0);
            parcel.setDataPosition(0);
            Intent result = Intent.CREATOR.createFromParcel(parcel);
            result.setExtrasClassLoader(ThrowingParcelable.class.getClassLoader());
            return result;
        } finally {
            parcel.recycle();
        }
    }

    public static final class HookActivity extends Activity {
        public String message;
    }

    public static final class ThrowingParcelable implements Parcelable {
        public static final Creator<ThrowingParcelable> CREATOR = new Creator<ThrowingParcelable>() {
            @Override
            public ThrowingParcelable createFromParcel(Parcel source) {
                throw new BadParcelableException("malformed test payload");
            }

            @Override
            public ThrowingParcelable[] newArray(int size) {
                return new ThrowingParcelable[size];
            }
        };

        @Override
        public int describeContents() {
            return 0;
        }

        @Override
        public void writeToParcel(Parcel dest, int flags) {
            dest.writeInt(1);
        }
    }
}

package com.alibaba.android.arouter.demo;

import android.app.Activity;
import android.content.Intent;

import androidx.core.app.ActivityCompat;

import com.alibaba.android.arouter.facade.Postcard;
import com.alibaba.android.arouter.facade.callback.NavigationCallback;
import com.alibaba.android.arouter.facade.callback.NavigationLauncher;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;

/**
 * Host activity used by the demo's navigation result tests.
 */
public class ActivityResultHostActivity extends Activity {
    static final int REQUEST_CODE = 905;

    private final CountDownLatch resultReceived = new CountDownLatch(1);
    private volatile int receivedRequestCode = -1;
    private volatile int receivedResultCode = Integer.MIN_VALUE;
    private volatile Intent receivedData;

    void navigateForResult(Postcard postcard, NavigationCallback callback) {
        postcard.navigation(getApplicationContext(), new NavigationLauncher() {
            @Override
            public void launch(Intent intent) {
                ActivityCompat.startActivityForResult(
                        ActivityResultHostActivity.this,
                        intent,
                        REQUEST_CODE,
                        null
                );
            }
        }, callback);
    }

    void navigateWithLegacyRequestCode(Postcard postcard, NavigationCallback callback) {
        postcard.navigation(this, REQUEST_CODE, callback);
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        receivedRequestCode = requestCode;
        receivedResultCode = resultCode;
        receivedData = data;
        resultReceived.countDown();
    }

    boolean awaitResult() throws InterruptedException {
        return resultReceived.await(5, TimeUnit.SECONDS);
    }

    int getReceivedRequestCode() {
        return receivedRequestCode;
    }

    int getReceivedResultCode() {
        return receivedResultCode;
    }

    Intent getReceivedData() {
        return receivedData;
    }
}

//! Run-scoped metadata intents for attaching workspace files to a final reply.
//!
//! This contract deliberately stores only stable scoped paths and bounded file
//! metadata. File bytes remain in the workspace filesystem and provider
//! delivery remains the responsibility of the transport layer.

use async_trait::async_trait;
use ironclaw_attachments::DEFAULT_ATTACHMENT_BUDGETS;
use ironclaw_host_api::{ids::RunId, path::ScopedPath, resource::ResourceScope};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

use crate::OutboundError;

const MAX_REPLY_ATTACHMENT_FILENAME_BYTES: usize = 255;
const MAX_REPLY_ATTACHMENT_MIME_TYPE_BYTES: usize = 127;

/// Opaque model-visible identity for one registered reply attachment.
///
/// The handle is deterministic for a `(run, scoped path)` pair so capability
/// retries and transcript finalization independently derive the same value
/// without persisting a second identifier or exposing the workspace path.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize)]
#[serde(transparent)]
pub struct ReplyAttachmentHandle(String);

impl ReplyAttachmentHandle {
    pub fn for_run_path(run_id: &RunId, path: &ScopedPath) -> Self {
        let mut digest = Sha256::new();
        digest.update(run_id.as_uuid().as_bytes());
        digest.update([0]);
        digest.update(path.as_str().as_bytes());
        Self(format!("att_{}", hex::encode(digest.finalize())))
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl std::fmt::Display for ReplyAttachmentHandle {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str(&self.0)
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ReplyAttachmentIntent {
    pub path: ScopedPath,
    pub filename: String,
    pub mime_type: String,
    pub size_bytes: u64,
}

impl ReplyAttachmentIntent {
    /// Validate that this metadata-only intent is safe and within the shared
    /// per-file budget. Aggregate count/byte limits are enforced by the store.
    pub fn validate(&self) -> Result<(), OutboundError> {
        validate_reply_attachment_intent(self)
    }
}

#[async_trait]
pub trait ReplyAttachmentIntentPort: Send + Sync {
    async fn register(
        &self,
        scope: &ResourceScope,
        run_id: &RunId,
        intent: ReplyAttachmentIntent,
    ) -> Result<(), OutboundError>;

    async fn seal(
        &self,
        scope: &ResourceScope,
        run_id: &RunId,
    ) -> Result<Vec<ReplyAttachmentIntent>, OutboundError>;
}

pub(crate) fn validate_reply_attachment_intent(
    intent: &ReplyAttachmentIntent,
) -> Result<(), OutboundError> {
    let Some(relative_path) = intent.path.as_str().strip_prefix("/workspace/") else {
        return Err(OutboundError::InvalidRequest {
            reason: "reply attachment path must be inside /workspace",
        });
    };
    if relative_path.is_empty() {
        return Err(OutboundError::InvalidRequest {
            reason: "reply attachment path must name a workspace file",
        });
    }
    if !is_safe_filename(&intent.filename) {
        return Err(OutboundError::InvalidRequest {
            reason: "reply attachment filename is invalid",
        });
    }
    if !is_valid_mime_type(&intent.mime_type) {
        return Err(OutboundError::InvalidRequest {
            reason: "reply attachment MIME type is invalid",
        });
    }
    if intent.size_bytes > DEFAULT_ATTACHMENT_BUDGETS.max_file_bytes as u64 {
        return Err(OutboundError::ReplyAttachmentIntentLimitExceeded);
    }
    Ok(())
}

pub(crate) fn validate_reply_attachment_intents(
    intents: &[ReplyAttachmentIntent],
) -> Result<(), OutboundError> {
    if intents.len() > DEFAULT_ATTACHMENT_BUDGETS.max_count {
        return Err(OutboundError::ReplyAttachmentIntentLimitExceeded);
    }

    let mut total_bytes = 0_u64;
    for (index, intent) in intents.iter().enumerate() {
        validate_reply_attachment_intent(intent)?;
        if intents[..index]
            .iter()
            .any(|existing| existing.path == intent.path)
        {
            return Err(OutboundError::ReplyAttachmentIntentConflict);
        }
        total_bytes = total_bytes
            .checked_add(intent.size_bytes)
            .ok_or(OutboundError::ReplyAttachmentIntentLimitExceeded)?;
    }
    if total_bytes > DEFAULT_ATTACHMENT_BUDGETS.max_total_bytes as u64 {
        return Err(OutboundError::ReplyAttachmentIntentLimitExceeded);
    }
    Ok(())
}

fn is_safe_filename(filename: &str) -> bool {
    !filename.is_empty()
        && filename.len() <= MAX_REPLY_ATTACHMENT_FILENAME_BYTES
        && filename != "."
        && filename != ".."
        && !filename
            .chars()
            .any(|character| character.is_control() || matches!(character, '/' | '\\'))
}

fn is_valid_mime_type(mime_type: &str) -> bool {
    if mime_type.is_empty() || mime_type.len() > MAX_REPLY_ATTACHMENT_MIME_TYPE_BYTES {
        return false;
    }
    let Some((top_level, subtype)) = mime_type.split_once('/') else {
        return false;
    };
    !top_level.is_empty()
        && !subtype.is_empty()
        && !subtype.contains('/')
        && top_level.chars().all(is_mime_token_character)
        && subtype.chars().all(is_mime_token_character)
}

fn is_mime_token_character(character: char) -> bool {
    character.is_ascii_alphanumeric()
        || matches!(
            character,
            '!' | '#' | '$' | '&' | '^' | '_' | '.' | '+' | '-'
        )
}

#[cfg(test)]
mod tests {
